using System;

public class Stack<T>
{
    private T[] stack;
    private int top;

    public Stack(int initialCapacity = 10)
    {
        stack = new T[initialCapacity];
        top = -1;
    }

    public void Push(T item)
    {
        if (top == stack.Length - 1)
        {
            Resize(2 * stack.Length);
        }
        stack[++top] = item;
    }

    public T Pop()
    {
        if (IsEmpty())
        {
            throw new InvalidOperationException("Stack is empty");
        }
        T item = stack[top];
        stack[top] = default(T);
        top -= 1;
        if (top > 0 && top == stack.Length / 4)
        {
            Resize(stack.Length / 2);
        }
        return item;
    }

    public T Peek()
    {
        if (IsEmpty())
        {
            throw new InvalidOperationException("Stack is empty");
        }
        return stack[top];
    }

    public bool IsEmpty()
    {
        return top == -1;
    }

    public int Size()
    {
        return top + 1;
    }

    private void Resize(int capacity)
    {
        T[] temp = new T[capacity];
        for (int i = 0; i <= top; i++)
        {
            temp[i] = stack[i];
        }
        stack = temp;
    }
}

class Program
{
    static void Main(string[] args)
    {
        Stack<int> stack = new Stack<int>();
        stack.Push(1);
        stack.Push(2);
        stack.Push(3);
        Console.WriteLine(stack.Pop());  // prints: 3
        Console.WriteLine(stack.Pop());  // prints: 2
        Console.WriteLine(stack.Pop());  // prints: 1
        try
        {
            Console.WriteLine(stack.Pop());  // raises exception: Stack is empty
        }
        catch (InvalidOperationException e)
        {
            Console.WriteLine(e.Message);  // prints: Stack is empty
        }
    }
}
```

