```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class RouteOptimizationEngine
{
    // Dijkstra's algorithm implementation for route optimization
    public RouteOptimizeResponse OptimizeRoute(Location start, Location end, Dictionary<Location, Dictionary<Location, int>> graph)
    {
        var shortestDistances = new Dictionary<Location, int>();
        var predecessors = new Dictionary<Location, Location>();
        var unseenNodes = new List<Location>(graph.Keys);
        var infinity = int.MaxValue;
        var path = new List<Location>();

        foreach (var node in unseenNodes)
        {
            shortestDistances[node] = infinity;
        }

        shortestDistances[start] = 0;

        while (unseenNodes.Count > 0)
        {
            var currentNode = GetLowestDistanceNode(unseenNodes, shortestDistances);

            unseenNodes.Remove(currentNode);

            var neighbors = graph[currentNode];

            foreach (var neighbor in neighbors)
            {
                var weight = neighbor.Value;
                if (weight + shortestDistances[currentNode] < shortestDistances[neighbor.Key])
                {
                    shortestDistances[neighbor.Key] = weight + shortestDistances[currentNode];
                    predecessors[neighbor.Key] = currentNode;
                }
            }
        }

        var longestDistanceNode = end;
        while (longestDistanceNode != null)
        {
            path.Add(longestDistanceNode);
            longestDistanceNode = predecessors.ContainsKey(longestDistanceNode) ? predecessors[longestDistanceNode] : null;
        }

        path.Reverse();

        return new RouteOptimizeResponse(path, shortestDistances[end]);
    }

    private Location GetLowestDistanceNode(List<Location> unseenNodes, Dictionary<Location, int> shortestDistances)
    {
        return unseenNodes.OrderBy(n => shortestDistances[n]).First();
    }
}

public class RouteOptimizeResponse
{
    public List<Location> Path { get; }
    public int Distance { get; }

    public RouteOptimizeResponse(List<Location> path, int distance)
    {
        Path = path;
        Distance = distance;
    }
}

