{
    public void UpdateLiveTraffic(Dictionary<Location, Dictionary<Location, int>> graph)
    {
        // Simulate live traffic data updates (e.g., from a database or API)
        foreach (var node in graph)
        {
            foreach (var neighbor in node.Value)
            {
                // Simulate dynamic weight updates
                neighbor.Value = (int)(neighbor.Value * (1 + new Random().NextDouble() / 10)); // 10% random variation
            }
        }
    }
}
