**Modular Cloud-Native API Gateway in C#**

This implementation will cover the three required features:

1.  **Reverse Proxy Forwarder**: routing requests to downstream microservice clusters
2.  **JWT Authentication and Authorization Subsystem**: validating cryptographic signatures and permission scopes
3.  **Distributed Tracing Middleware**: injecting correlation IDs into request headers

### Reverse Proxy Forwarder

We'll utilize the `AspNetCore.Http` and `Microsoft.AspNetCore.Builder` namespaces to create a reverse proxy forwarder. This example assumes you have a downstream microservice cluster running on `http://localhost:5001`.

```csharp
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.Threading.Tasks;

public class Startup
{
    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        // Forward requests to the downstream microservice cluster
        app.UseForwardedHeaders(new ForwardedHeadersOptions
        {
            ForwardedHeaders = ForwardedHeaders.XForwardedFor | ForwardedHeaders.XForwardedProto
        });

        app.UseRouting();

        app.UseEndpoints(endpoints =>
        {
            endpoints.Map("/api/*", async context =>
            {
                // Create a new HTTP client instance
                var httpClient = context.RequestServices.GetService<IHttpClientFactory>().CreateClient();

                // Forward the request to the downstream microservice cluster
                var request = context.Request;
                var downstreamUrl = "http://localhost:5001" + request.Path;

                var downstreamRequest = new HttpRequestMessage(request.Method, downstreamUrl);
                foreach (var header in request.Headers)
                {
                    downstreamRequest.Headers.TryAddWithoutValidation(header.Key, header.Value.ToArray());
                }

                var downstreamResponse = await httpClient.SendAsync(downstreamRequest);

                // Copy the response from the downstream microservice back to the original client
                await CopyResponse(context, downstreamResponse);
            });
        });
    }

    private async Task CopyResponse(HttpContext context, HttpResponseMessage downstreamResponse)
    {
        context.Response.StatusCode = (int)downstreamResponse.StatusCode;

        foreach (var header in downstreamResponse.Headers)
        {
            context.Response.Headers.Add(header.Key, header.Value.ToArray());
        }

        await downstreamResponse.Content.CopyToAsync(context.Response.Body);
    }
}
```

### JWT Authentication and Authorization Subsystem

We'll utilize the `System.IdentityModel.Tokens.Jwt` and `Microsoft.AspNetCore.Authentication.JwtBearer` namespaces to create a JWT authentication and authorization subsystem.

```csharp
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using System.Threading.Tasks;

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Configure JWT authentication settings
        services.Configure<JwtSettings>(configuration.GetSection("JwtSettings"));

        // Add JWT authentication and authorization
        services.AddAuthentication(options =>
        {
            options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
            options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
        })
        .AddJwtBearer(options =>
        {
            options.SaveToken = true;
            options.RequireHttps = false; // Change to true in production
            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidateAudience = true,
                ValidateLifetime = true,
                ValidateIssuerSigningKey = true,
                ValidIssuer = configuration["JwtSettings:Issuer"],
                ValidAudience = configuration["JwtSettings:Audience"],
                IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(configuration["JwtSettings:SecretKey"]))
            };
            options.Events = new JwtBearerEvents
            {
                OnTokenValidated = context =>
                {
                    // Validate permission scopes
                    var permissions = context.Principal.FindAll("/permissions");
                    var requiredPermissions = context.Request.Path.Value.Split('/').Select(permission => $"/{permission}");

                    if (!requiredPermissions.All(permission => permissions.Contains(permission)))
                    {
                        context.Fail("Unauthorized");
                    }

                    return Task.CompletedTask;
                }
            };
        });

        services.AddAuthorization(options =>
        {
            options.AddPolicy("admin", policy => policy.RequireClaim("/admin"));
        });
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        // Add JWT authentication and authorization middleware
        app.UseAuthentication();
        app.UseAuthorization();

        // Example usage: protect a route with the "admin" policy
        app.Map("/admin", admin =>
        {
            admin.RequireAuthorization("admin");
            admin.Run(async context =>
            {
                await context.Response.WriteAsync("Hello, admin!");
            });
        });
    }
}

public class JwtSettings
{
    public string Issuer { get; set; }
    public string Audience { get; set; }
    public string SecretKey { get; set; }
}
```

### Distributed Tracing Middleware

We'll utilize the `OpenTracing` namespace to create a distributed tracing middleware.

```csharp
using OpenTracing;
using OpenTracing.Util;
using System;
using System.Threading.Tasks;

public class DistributedTracingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ITracer _tracer;

    public DistributedTracingMiddleware(RequestDelegate next, ITracer tracer)
    {
        _next = next;
        _tracer = tracer;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Extract the incoming request's correlation ID (if any)
        var correlationId = context.Request.Headers["Correlation-Id"];

        ISpan span;

        // Create a new span if no correlation ID is present, or else join the existing span
        if (string.IsNullOrEmpty(correlationId))
        {
            span = _tracer.BuildSpan("Incoming Request")
                .WithTag("component", "DistributedTracingMiddleware")
                .StartSpan();
        }
        else
        {
            span = _tracer.BuildSpan("Incoming Request")
                .WithTag("component", "DistributedTracingMiddleware")
                .WithReference(References.ChildOf(correlationId))
                .StartSpan();
        }

        // Add the correlation ID to the outgoing response headers
        context.Response.Headers.Add("Correlation-Id", span.Context.SpanId);

        // Continue the request pipeline
        await _next(context);

        // Finish the span
        span.Finish();
    }
}

public class Startup
{
    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        // Add distributed tracing middleware
        app.UseMiddleware<DistributedTracingMiddleware>();

        // Initialize the distributed tracing system
        app.ApplicationServices.GetService<ITracer>();
    }
}
```

