# Modular Distributed Job Execution Framework
==============================================

## Overview
-----------

This framework consists of three primary components:

1.  **Master Coordinator**: Responsible for managing task distribution and monitoring worker heartbeats.
2.  **Worker Agent**: Executes tasks in isolated containers with CPU and memory caps.
3.  **Result Aggregator**: Collects task outputs and manages failure retries.

## Framework Implementation
------------------------

### Master Coordinator

```python
# master_coordinator.py
import datetime
import threading
from queue import Queue
from typing import Dict, List

class MasterCoordinator:
    def __init__(self):
        self.task_queue = Queue()
        self.worker_heartbeats: Dict[str, datetime.datetime] = {}
        self.max_heartbeat_timeout = 60  # seconds

    def add_task(self, task_id: str, task_data: str):
        self.task_queue.put((task_id, task_data))

    def start_worker_heartbeat_monitor(self):
        def monitor_heartbeats():
            while True:
                current_time = datetime.datetime.now()
                for worker_id, heartbeat_time in list(self.worker_heartbeats.items()):
                    if (current_time - heartbeat_time).total_seconds() > self.max_heartbeat_timeout:
                        print(f"Worker {worker_id} timed out. Removing from heartbeat list.")
                        del self.worker_heartbeats[worker_id]
                threading.sleep(1)

        threading.Thread(target=monitor_heartbeats).start()

    def update_worker_heartbeat(self, worker_id: str):
        self.worker_heartbeats[worker_id] = datetime.datetime.now()

    def get_tasks_for_worker(self, worker_id: str, num_tasks: int) -> List[tuple]:
        tasks = []
        for _ in range(num_tasks):
            if not self.task_queue.empty():
                task_id, task_data = self.task_queue.get()
                tasks.append((task_id, task_data))
        return tasks
```

### Worker Agent

```python
# worker_agent.py
import containerization
import subprocess
from typing import List, Tuple

class WorkerAgent:
    def __init__(self, worker_id: str, master_coordinator: MasterCoordinator):
        self.worker_id = worker_id
        self.master_coordinator = master_coordinator
        self.container = None

    def start_container(self, cpu_cap: int, mem_cap: int):
        self.container = containerization.start_container(cpu_cap, mem_cap)

    def execute_task(self, task_id: str, task_data: str) -> Tuple[bool, str]:
        try:
            # Execute task in container
            output = subprocess.check_output(["/bin/sh", "-c", f"echo '{task_data}' > task_input.txt"], cwd=self.container)
            return True, output.decode("utf-8")
        except subprocess.CalledProcessError as e:
            return False, str(e)

    def update_heartbeat(self):
        self.master_coordinator.update_worker_heartbeat(self.worker_id)

    def get_tasks(self, num_tasks: int) -> List[Tuple[str, str]]:
        return self.master_coordinator.get_tasks_for_worker(self.worker_id, num_tasks)

    def run(self):
        self.start_container(2, 1024)  # Example: 2 CPU cores, 1024 MB memory
        while True:
            tasks = self.get_tasks(5)  # Get 5 tasks from master coordinator
            for task_id, task_data in tasks:
                success, output = self.execute_task(task_id, task_data)
                if success:
                    print(f"Task {task_id} executed successfully: {output}")
                else:
                    print(f"Task {task_id} failed: {output}")
            self.update_heartbeat()
```

### Result Aggregator

```python
# result_aggregator.py
from typing import Dict, List, Tuple

class ResultAggregator:
    def __init__(self):
        self.results: Dict[str, str] = {}
        self.failure_count: Dict[str, int] = {}

    def add_result(self, task_id: str, output: str):
        self.results[task_id] = output

    def add_failure(self, task_id: str):
        if task_id not in self.failure_count:
            self.failure_count[task_id] = 0
        self.failure_count[task_id] += 1

    def retry_failed_tasks(self, max_retries: int):
        failed_tasks = [task_id for task_id, count in self.failure_count.items() if count < max_retries]
        return failed_tasks

    def get_results(self) -> Dict[str, str]:
        return self.results
```

