        private readonly IUserDirectoryService _userDirectoryService;

        public OpenIDConnectController(IConfiguration configuration, IUserDirectoryService userDirectoryService)
        {
            _configuration = configuration;
            _userDirectoryService = userDirectoryService;
        }

        [HttpPost("token")]
        public async Task<IActionResult> GetToken([FromBody] TokenRequest request)
        {
            // Authenticate the user
            var user = await _userDirectoryService.GetUser(request.Username);
            if (user == null || !await _userDirectoryService.VerifyPassword(user, request.Password))
            {
                return Unauthorized();
            }

            // Generate JWT token
            var tokenHandler = new JwtSecurityTokenHandler();
            var key = Encoding.ASCII.GetBytes(_configuration["SecretKey"]);
            var tokenDescriptor = new SecurityTokenDescriptor
            {
                Subject = new ClaimsIdentity(new[] { new Claim("id", user.Id) }),
                Expires = DateTime.UtcNow.AddHours(1),
                SigningCredentials = new SigningCredentials(new SymmetricSecurityKey(key), SecurityAlgorithms.HmacSha256Signature)
            };
            var token = tokenHandler.CreateToken(tokenDescriptor);
            var tokenString = tokenHandler.WriteToken(token);

            return Ok(new { access_token = tokenString });
        }
    }

