    private Dictionary<string, int> queues;
    private double greenLightDuration;
    private int maxGreenLightDuration;
    private int minGreenLightDuration;

    public AdaptiveTimingOptimizationEngine(Dictionary<string, int> queues)
    {
        this.queues = queues;
        greenLightDuration = 30;
        maxGreenLightDuration = 60;
        minGreenLightDuration = 10;
    }

    public double Optimize()
    {
        int totalVehicles = 0;
        foreach (var queue in queues)
        {
            totalVehicles += queue.Value;
        }

        if (totalVehicles > 50)
        {
            greenLightDuration = Math.Min(greenLightDuration + 1, maxGreenLightDuration);
        }
        else if (totalVehicles < 5)
        {
            greenLightDuration = Math.Max(greenLightDuration - 1, minGreenLightDuration);
        }

        return greenLightDuration;
    }
