public class SagaTransactionCoordinator : ISagaTransactionCoordinator
{
    private readonly IInventoryService _inventoryService;
    private readonly IPaymentService _paymentService;
    private readonly IShippingService _shippingService;

    public SagaTransactionCoordinator(IInventoryService inventoryService, IPaymentService paymentService, IShippingService shippingService)
    {
        _inventoryService = inventoryService;
        _paymentService = paymentService;
        _shippingService = shippingService;
    }

    public void ProcessTransaction(ShoppingCart cart)
    {
        try
        {
            // Reserve inventory
            _inventoryService.ReserveInventory(cart);

            // Process payment
            _paymentService.ProcessPayment(cart);

            // Ship order
            _shippingService.ShipOrder(cart);

            // Commit transaction
            _inventoryService.CommitInventory();
            _paymentService.CommitPayment();
            _shippingService.CommitShipment();
        }
        catch (Exception ex)
        {
            // Rollback transaction
            _inventoryService.RollbackInventory();
            _paymentService.RollbackPayment();
            _shippingService.RollbackShipment();
            throw; // Rethrow the exception
        }
    }
}

