    {
        _spillDirectory = spillDirectory;
    }

    // Spill the aggregation groups to disk
    public void Spill(Dictionary<int, AggregationGroup> aggregationGroups)
    {
        foreach (var group in aggregationGroups.Values)
        {
            using (var fileStream = new FileStream(Path.Combine(_spillDirectory, group.GetSum().ToString()), FileMode.Create))
            {
                using (var binaryWriter = new BinaryWriter(fileStream))
                {
                    // Serialize the group to disk
                    binaryWriter.Write(group.GetSum());
                }
            }
        }
    }

    // Load the spilled data from disk
    public Dictionary<int, AggregationGroup> LoadSpilledData()
    {
        var aggregationGroups = new Dictionary<int, AggregationGroup>();

        foreach (var file in Directory.GetFiles(_spillDirectory))
        {
            using (var fileStream = new FileStream(file, FileMode.Open))
            {
                using (var binaryReader = new BinaryReader(fileStream))
                {
                    // Deserialize the group from disk
                    var sum = binaryReader.ReadInt32();
                    var group = new AggregationGroup(sum);
                    aggregationGroups.Add(sum, group);
                }
            }
        }

        return aggregationGroups;
    }
}
```

